#!/usr/bin/env bash
# Static preflight for Phase 13N. It never launches third-party Skill code.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT"
fail() { echo "Phase 13N PREFLIGHT FAILED: $*" >&2; exit 1; }

for file in \
  lib/core/services/skills/skill_execution_permissions.dart \
  lib/core/services/skills/skill_execution_security.dart \
  lib/core/services/skills/skill_executor.dart \
  lib/core/services/extensions/extension_permission_policy.dart \
  lib/features/home/services/tool_handler_service.dart \
  lib/core/services/extensions/skill_execution_tools.dart \
  android/app/src/main/kotlin/com/psyche/kelivo/workspace/MountWriteGuards.kt \
  android/app/src/main/kotlin/com/psyche/kelivo/workspace/WorkspacePlugin.kt \
  android/app/src/main/kotlin/com/psyche/kelivo/workspace/ExecRunner.kt \
  android/app/src/main/kotlin/com/psyche/kelivo/workspace/ProotCommand.kt \
  test/core/services/skills/skill_execution_permissions_test.dart \
  test/core/services/skills/skill_execution_security_test.dart \
  test/core/services/skills/skill_executor_test.dart \
  test/core/services/extensions/extension_permission_policy_test.dart \
  android/app/src/test/kotlin/com/psyche/kelivo/workspace/MountWriteGuardsTest.kt \
  .github/scripts/run_phase13n_tests.sh \
  .github/scripts/test_phase13n_ci.sh \
  phases/PHASE-13N-UNIVERSAL-SKILL-SANDBOX-AND-PERMISSIONS-AR.md; do
  [[ -s "$file" ]] || fail "Missing or empty Phase 13N component: $file"
done

python3 - <<'PY_PHASE13N'
from pathlib import Path
policy = Path('lib/core/services/skills/skill_execution_permissions.dart').read_text(encoding='utf-8')
executor = Path('lib/core/services/skills/skill_executor.dart').read_text(encoding='utf-8')
security = Path('lib/core/services/skills/skill_execution_security.dart').read_text(encoding='utf-8')
handler = Path('lib/features/home/services/tool_handler_service.dart').read_text(encoding='utf-8')
tool_schema = Path('lib/core/services/extensions/skill_execution_tools.dart').read_text(encoding='utf-8')
permission_catalog = Path('lib/core/services/extensions/extension_permission_policy.dart').read_text(encoding='utf-8')
guards = Path('android/app/src/main/kotlin/com/psyche/kelivo/workspace/MountWriteGuards.kt').read_text(encoding='utf-8')
workspace = Path('android/app/src/main/kotlin/com/psyche/kelivo/workspace/WorkspacePlugin.kt').read_text(encoding='utf-8')
exec_runner = Path('android/app/src/main/kotlin/com/psyche/kelivo/workspace/ExecRunner.kt').read_text(encoding='utf-8')
proot = Path('android/app/src/main/kotlin/com/psyche/kelivo/workspace/ProotCommand.kt').read_text(encoding='utf-8')
executor_test = Path('test/core/services/skills/skill_executor_test.dart').read_text(encoding='utf-8')
permission_test = Path('test/core/services/skills/skill_execution_permissions_test.dart').read_text(encoding='utf-8')
native_test = Path('android/app/src/test/kotlin/com/psyche/kelivo/workspace/MountWriteGuardsTest.kt').read_text(encoding='utf-8')
workflow = Path('.github/workflows/android-build.yml').read_text(encoding='utf-8')
runner = Path('.github/scripts/run_phase13n_tests.sh').read_text(encoding='utf-8')
report = Path('phases/PHASE-13N-UNIVERSAL-SKILL-SANDBOX-AND-PERMISSIONS-AR.md').read_text(encoding='utf-8')

checks = [
    ('current local-script adapter declares every actually exposed high-risk capability', all(k in policy for k in ["'skill.runtime.execute'", "'runtime.rootfs.write'", "'network.read'", "'network.write'", "'network.package_install'", "'external.services'"])),
    ('unknown and known-but-unsupported permissions fail closed', 'unknownPermissions' in policy and 'permission_requires_native_adapter' in policy and "'blockedUntilReviewed': true" in policy),
    ('single-run grants are bound to the exact in-memory object and consumed at dispatch', all(k in policy for k in ['Expando<String>', '_singleRunGrantIds[approved] = grantId', '_singleRunGrantIds[permissionReview] = null'])),
    ('executor validates grant before parsing or dispatching skill code', executor.find('validateSingleRunGrant(') < executor.find('_parseManifest(')),
    ('skill invocation approval is mandatory for every run and grant is created only after approval returns', (lambda h: h.find('await permission.authorize(') < h.find('executor.execute(') < h.find('SkillExecutionPermissionPolicy.approveForSingleRun(') and 'requireManualApproval: true' in h)(handler[handler.find('final permissionReview = SkillExecutionPermissionPolicy.reviewForSkill'):])) ,
    ('grant token is generated by the host and is absent from the model tool schema', 'const Uuid().v4()' in handler and 'execution_grant_id' not in tool_schema),
    ('source and input are separate read-only-requested mounts; output and tmp are separate writable mounts', all(k in executor for k in ["guest: sourceGuest", "guest: '$ioGuest/input'", "guest: '$ioGuest/output'", "guest: '$ioGuest/tmp'", "readOnly: true"])),
    ('KELIVO command guards precede profile paths while preserving Python/Node paths', "'PATH': _guardedSkillPath(profileExecution.environment['PATH'])" in executor and "'/usr/local/bin'" in executor and "'/usr/local/sbin'" in executor),
    ('permission and approval reports explicitly disclose shared writable RootFS and unrestricted network', 'shared and writable' in security and 'cannot deny' in security and "'kernelIsolation': false" in security),
    ('native guard configuration is unique for each Skill run', 'prepareForRun' in guards and 'run-$runId' in guards and 'KELIVO_READONLY_MOUNTS_FILE' in guards and 'releaseForRun' in guards),
    ('Android Exec binds request-specific guard path and cleans it after pre-launch failure', 'readOnlyGuardConfigFile = guard?.file' in workspace and 'MountWriteGuards.releaseForRun(request.rootfsDir, request.readOnlyGuardConfigFile)' in exec_runner),
    ('PRoot read-only behavior is not represented as kernel-enforced', 'best-effort' in guards and 'PRoot' in report and 'Kernel' in report and 'does not provide kernel-enforced read-only' in executor),
    ('tests cover one-time grant replay, mismatched grant, separate mounts and Android run concurrency', all(k in permission_test for k in ['cannot be replayed']) and all(k in executor_test for k in ['mismatched single-run permission grant', 'io/input', 'io/output']) and 'runScopedConfigsDoNotOverwriteConcurrentSkillGuards' in native_test),
    ('focused CI runner contains permission, security, extension and executor suites', all(k in runner for k in ['skill_execution_permissions_test.dart', 'skill_execution_security_test.dart', 'extension_permission_policy_test.dart', 'skill_executor_test.dart'])),
    ('Phase 13N workflow includes Dart checks, focused tests and Android native guard tests', all(k in workflow for k in ['phase13n_syntax_preflight', 'phase13n_ci_self_test', 'phase13n_preflight', 'phase13n_tests', 'phase13n_android_guard_tests', 'MountWriteGuardsTest'])),
]
for label, ok in checks:
    if not ok:
        raise SystemExit(f'FAIL: {label}')
    print(f'PASS: {label}')

# The generic security/execution engine must not be tied to the six example Skills.
sample_ids = ['ig-profile', 'ig-reel', 'ig-viral', 'animation-director', 'arabian-motion-video-director', 'character-visual-director']
for filename in [
    'lib/core/services/skills/skill_execution_permissions.dart',
    'lib/core/services/skills/skill_execution_security.dart',
    'lib/core/services/skills/skill_executor.dart',
    'android/app/src/main/kotlin/com/psyche/kelivo/workspace/MountWriteGuards.kt',
]:
    content = Path(filename).read_text(encoding='utf-8').lower()
    for sample_id in sample_ids:
        if sample_id in content:
            raise SystemExit(f'FAIL: generic execution policy is hard-coded to example Skill {sample_id} in {filename}')
print('PASS: universal execution and security adapters do not depend on the six sample Skill IDs')
PY_PHASE13N

bash -n .github/scripts/preflight_phase13n_tests.sh
bash -n .github/scripts/run_phase13n_tests.sh

echo 'Phase 13N static preflight passed.'
